import GroupedDataInteraction from '../../grouped-data-interaction/grouped-data-interaction';
import { Statement } from '../../types/statement';
import StatementVerbHelper from '../statement/verb';

export default class InteractionHelper {
  /**
   * Add statements to interactions
   *
   * @param statements - A list of Statement objects
   * @param interactions - A list of GroupedDataInteraction objects
   */
  public static addStatementsToInteractions(
    statements: Statement[],
    interactionHashes: Map<string, number>,
    interactions: GroupedDataInteraction[],
  ) {
    statements.forEach((statement, statementId) => {
      // Get the index of the interaction
      const interactionIndex = interactionHashes.get(statement.object.id);

      if (interactionIndex !== undefined) {
        // Get the interaction and add the statementId
        interactions[interactionIndex].addStatement(statementId);
      }
    });
  }

  /**
    * Check if the interaction has been passed by checking if any of the statements have a
    * success and completion result
    *
    * @param statements - A list of Statement objects
    * @param interaction - A GroupedDataInteraction object
    */
  public static hasPassed({ statements, interaction }: {
    statements: Statement[];
    interaction: GroupedDataInteraction;
  }): boolean {
    const usedStatements = interaction.statementIdxs.map((statementId) => statements[statementId]);
    return StatementVerbHelper.getStatementsWithScoreExtension(usedStatements).filter(
      (statement) => statement.result?.success && statement.result?.completion,
    ).length > 0;
  }

  /**
    * Check if the interaction has been completed by checking if any of the statements have a
    * success and completion result
    *
    * @param statements - A list of Statement objects
    * @param interaction - A GroupedDataInteraction object
    */
  public static hasCompleted({ statements, interaction }: {
    statements: Statement[];
    interaction: GroupedDataInteraction;
  }): boolean {
    const usedStatements = interaction.statementIdxs.map((statementId) => statements[statementId]);
    return StatementVerbHelper.getStatementsWithScoreExtension(usedStatements).filter(
      (statement) => statement.result?.completion,
    ).length > 0;
  }

  /**
    * Check if the interaction has been started by checking if any of the statements have a
    * success and completion result
    *
    * @param statements - A list of Statement objects
    * @param interaction - A GroupedDataInteraction object
    */
  public static hasStarted({ statements, interaction }: {
    statements: Statement[];
    interaction: GroupedDataInteraction;
  }): boolean {
    const usedStatements = interaction.statementIdxs.map((statementId) => statements[statementId]);
    return StatementVerbHelper.getStatementsByInitializedVerb(usedStatements).length > 0;
  }
}
