import GroupedDataInteraction from '../grouped-data-interaction/grouped-data-interaction';
import GroupedDataLearningObject from '../grouped-data-learning-object/grouped-data-learning-object';
import GroupedDataModule from '../grouped-data-module/grouped-data-module';
import GroupedDataUser from '../grouped-data-user/grouped-data-user';
import InteractionHelper from '../helpers/interaction/interaction';
import initiateLearningObjectsFromStatements from '../helpers/learningObject';
import { sortStatementsAsc } from '../helpers/statement/sort';
import StatementHelper from '../helpers/statement/statement';
import StatementInteractionHelper from '../helpers/statementInteraction';
import UserHelper from '../helpers/user/user';
import { IGroupedData } from '../interfaces/IGroupedData';
import { EXTENSION_URL_SESSION_ID } from '../types/extension';
import { Statement, validateStatements } from '../types/statement';
import { StatementInteraction } from '../types/statement-interactions';
import { User } from '../types/user';
import { WindowModule } from '../types/window-module';

export default class GroupedData implements IGroupedData {
  /** The interactions */
  public get interactions(): GroupedDataInteraction[] {
    return this.#interactions;
  }

  /** A set of modules */
  public get modules(): GroupedDataModule[] | undefined {
    return this.#modules;
  }

  /** A set of raw statements */
  public get statements(): Statement[] {
    return this.#statements;
  }

  /** A set of statement indexes */
  public get statementIdxs(): Set<number> {
    return this.#statementIdxs;
  }

  /** A set of users */
  public get users(): GroupedDataUser[] {
    return this.#users;
  }

  #interactions: GroupedDataInteraction[];

  #interactionHashes: Map<string, number>;

  #learningObjects: GroupedDataLearningObject[];

  #modules: GroupedDataModule[] | undefined;

  #moduleHashes: Map<string, number> | undefined;

  #statements: Statement[];

  #statementIdxs: Set<number> = new Set();

  #statementInteractions: StatementInteraction[] | undefined;

  #users: GroupedDataUser[];

  #userHashes: Map<string, number>;

  #windowModule: WindowModule | undefined;

  /**
   * Constructor for GroupedData
   *
   * @param statements - A list of Statement objects
   * @param windowModule - A WindowModule object
   * @param users - A list of User objects
   */
  public constructor(statements: Statement[], windowModule?: WindowModule, users?: User[]) {
    // Validate the statements
    this.#statements = validateStatements(statements);

    // Initiate the learning objects
    this.#learningObjects = initiateLearningObjectsFromStatements(statements);

    // Initiate the statements interactions if no windowModule is provided. Sort the
    // statements in ascending order before to get the earliest interaction first.
    this.#statementInteractions = windowModule
      ? undefined
      : StatementInteractionHelper.initiateStatementInteractions(
        sortStatementsAsc(this.#statements),
      );

    // Initiate the interactions using the windowModule if provided, or the statement interactions
    // otherwise.
    if (windowModule) {
      this.#interactions = GroupedData.initiateInteractionsFromWindow(windowModule);
    } else if (this.#statementInteractions) {
      this.#interactions = GroupedData
        .initiateInteractionsFromStatementsInteractions(this.#statementInteractions!);
    } else {
      throw new Error('No interactions found');
    }

    // Initiate the interaction hashes if a windowModule is provided
    this.#interactionHashes = windowModule
      ? GroupedData.initiateInteractionHashesFromModules(windowModule)
      : GroupedData.initiateInteractionHashesFromLearningObjects(
        this.#interactions,
      );

    InteractionHelper.addStatementsToInteractions(
      this.#statements,
      this.#interactionHashes,
      this.#interactions,
    );

    // Initiate the users, either using the provided users or the statements
    this.#users = users
      ? UserHelper.initiateUsersFromUsers({ users, interactions: this.#interactions })
      : UserHelper.initiateUsersFromStatements(
        { statements: this.#statements, interactions: this.#interactions },
      );

    console.log('users', this.#users);

    // Initiate the modules if a windowModule is provided
    this.#modules = windowModule ? this.initiateModules(windowModule) : undefined;

    // Initiate the module hashes if a windowModule is provided
    this.#moduleHashes = windowModule ? GroupedData.initiateModuleHashes(windowModule) : undefined;

    // Initiate the user hashes
    this.initiateUserHashes();

    this.processStatements();
  }

  /**
   * Processes the statements
   */
  private processStatements(): void {
    this.#statements.forEach((statement, statementIdx) => {
      this.#statementIdxs.add(statementIdx);

      // Populate the module and user with the statement
      this.populateModule({ statement, statementIdx });
      this.populateUser({ statement, statementIdx });
    });

    // Prepare the statistics for all the users
    this.#users.forEach((user, userIndex) => {
      user.prepareStatistics({ statements: this.#statements });
    });
  }

  /**
   * Populates the user with a statement
   *
   * @param statement - A Statement object
   * @param statementIdx - The index of the statement
   */
  private populateUser({
    statement,
    statementIdx,
  }: {
    statement: Statement;
    statementIdx: number
  }): void {
    const userIndex = StatementHelper.getUserIndex(statement, this.#userHashes);
    if (userIndex >= 0) {
      const attemptKey = statement.context?.extensions[EXTENSION_URL_SESSION_ID];
      if (attemptKey !== undefined) {
        // Add the attempt to the user
        this.#users[userIndex].addAttempt(attemptKey, statementIdx);
      }
    }
  }

  /**
   * Populates the module with a statement
   *
   * @param statement - A Statement object
   * @param statementIdx - The index of the statement
   */
  private populateModule({
    statement,
    statementIdx,
  }: {
    statement: Statement;
    statementIdx: number
  }): void {
    if (
      this.#moduleHashes !== undefined
      && this.#windowModule !== undefined
      && this.#modules !== undefined
      && this.#interactionHashes !== undefined
    ) {
      const { module, moduleIndex } = GroupedDataModule.getModule(
        statement,
        this.#moduleHashes,
        this.#windowModule.usetemplateids === '1',
        this.#modules,
      );
      if (module !== undefined) {
        module.addStatement({
          statement,
          statementIdx,
          moduleIndex,
          interactionHashes: this.#interactionHashes,
          windowModule: this.#windowModule,
          userHashes: this.#userHashes,
        });
      }
    }
  }

  /**
   * Creates GroupedDataModule objects from the WindowModule module objects
   *
   * @param modules - A WindowModule object
   * @returns A set of GroupedDataModule objects
   */
  private initiateModules(windowModule: WindowModule): GroupedDataModule[] {
    return windowModule.modules.map(
      (module, moduleKey) => new GroupedDataModule(module, moduleKey, this.users),
    );
  }

  /**
   * Creates a hash map of modules to module indexes
   *
   * @param windowModule - A WindowModule object
   * @returns A map of modules to module indexes
   */
  private static initiateModuleHashes(windowModule: WindowModule): Map<string, number> {
    if (windowModule.usetemplateids) {
      return new Map(windowModule.modules.flatMap(
        (module, moduleKey) => (module.id !== null ? [[module.id, moduleKey]] : []),
      ));
    }
    return new Map(windowModule.modules.flatMap(
      (module, moduleKey) => (module.module !== null ? [[module.module, moduleKey]] : []),
    ));
  }

  /**
   * Initiates interactions from the window module
   *
   * @param windowModule - A WindowModule object
   * @returns An array of GroupedDataInteraction objects
   */
  private static initiateInteractionsFromWindow(
    windowModule: WindowModule,
  ): GroupedDataInteraction[] {
    return windowModule.modules.flatMap((module, moduleKey) => module.interactions.map(
      (interaction, interactionKey) => new GroupedDataInteraction(
        {
          module: moduleKey,
          key: interactionKey,
          statementIdxs: [],
          url: interaction.xapiobjectid,
          name: interaction.name,
        },
      ),
    ));
  }

  /**
   * Initiates interactions from the statement interactions. This is used
   * when no windowModule exists.
   *
   * @param statementInteractions - A list of Statement interaction objects
   * @returns An array of GroupedDataInteraction objects
   */
  private static initiateInteractionsFromStatementsInteractions(
    statementInteractions: StatementInteraction[],
  ): GroupedDataInteraction[] {
    return statementInteractions.map(
      (interaction, interactionKey) => new GroupedDataInteraction(
        {
          module: undefined,
          key: interactionKey,
          statementIdxs: [],
          url: interaction.url,
          name: interaction.name.en ?? interaction.name['en-US'] ?? interaction.url,
        },
      ),
    );
  }

  /**
   * Creates a hash map of interactions to interaction indexes per module
   *
   * @param windowModule - A WindowModule object
   * @returns A map of interaction to interaction indexes per module
   */
  private static initiateInteractionHashesFromModules(
    windowModule: WindowModule,
  ): Map<string, number> {
    let globalIndex = 0;
    const map = new Map();
    windowModule.modules.forEach((module) => {
      module.interactions.forEach(
        (interaction, interactionKey) => map.set(
          `${windowModule.xerteurl}${module.id}/${interaction.name}`,
          globalIndex + interactionKey,
        ),
      );
      globalIndex += 1;
    });
    return map;
  }

  /**
   * Creates a hash map of interactions to interaction indexes
   *
   * @param interactions - A list of GroupedDataInteraction objects
   * @returns A map of interaction to interaction indexes per learning object
   */
  private static initiateInteractionHashesFromLearningObjects(
    interactions: GroupedDataInteraction[],
  ): Map<string, number> {
    return new Map(
      interactions.map((interaction, interactionKey) => [interaction.url, interactionKey]),
    );
  }

  /**
   * Creates a hash map of users to user indexes
   */
  private initiateUserHashes(): void {
    this.#userHashes = this.#users.reduce((hash, user, userKey) => {
      hash.set(user.ifi.hash, userKey);
      return hash;
    }, new Map());
  }
}
