import GroupedDataInteraction from '../grouped-data-interaction/grouped-data-interaction';
import GroupedDataUser from '../grouped-data-user/grouped-data-user';
import StatementHelper from '../helpers/statement/statement';
import { IGroupedDataModule } from '../interfaces/IGroupedDataModule';
import { EXTENSION_URL_SESSION_ID } from '../types/extension';
import { Statement } from '../types/statement';
import { Module, WindowModule } from '../types/window-module';

export default class GroupedDataModule implements IGroupedDataModule {
  /** The id of the module */
  public get id(): string | null {
    return this.#id;
  }

  /** A list of interactions */
  public get interactions(): GroupedDataInteraction[] {
    return this.#interactions;
  }

  /** The name of the module */
  public get module(): string | null {
    return this.#module;
  }

  /** A list of statement indexes */
  public get statementIdxs(): number[] {
    return this.#statementIdxs;
  }

  /** A list of users of the module */
  public get users(): GroupedDataUser[] {
    return this.#users;
  }

  #id: string | null;

  #interactions: GroupedDataInteraction[];

  #module: string | null;

  #statementIdxs: number[];

  #users: GroupedDataUser[];

  /**
   * Constructor for GroupedDataModule
   *
   * @param module - A Module object
   * @param moduleKey - The key of the module
   * @param users - A list of GroupedDataUser objects
   */
  public constructor(module: Module, moduleKey: number, users: GroupedDataUser[] | undefined) {
    this.#id = module.id;
    this.#module = module.module;
    this.#statementIdxs = [];
    this.#users = users ?? [];
    // TODO: check if this is neccesary
    this.#interactions = module.interactions.map(
      (_interaction, interactionKey) => new GroupedDataInteraction(
        {
          module: moduleKey, key: interactionKey, statementIdxs: [], url: 'TODO: change me',
        },
      ),
    );
  }

  /**
   * Process the data from a statement and add it to the module
   *
   * @param statement - A Statement object
   * @param statementIdx - The index of the statement
   * @param moduleIndex - The index of the module
   * @param interactionHashes - A list of interaction hashes
   * @param windowModule - A WindowModule object
   * @param userHashes - A GroupedDataUserHash object
   */
  public addStatement({
    statement,
    statementIdx,
    moduleIndex,
    interactionHashes,
    windowModule,
    userHashes,
  }: {
    statement: Statement;
    statementIdx: number;
    moduleIndex: number;
    interactionHashes: Map<string, number>;
    windowModule: WindowModule;
    userHashes: Map<string, number>;
  }): void {
    this.statementIdxs.push(statementIdx);

    const interactionIndex = StatementHelper.getInteractionIndex(
      statement,
      interactionHashes,
      windowModule.xerteurl.length,
    );
    if (interactionIndex >= 0) {
      this
        .interactions[interactionIndex]
        .statementIdxs
        .push(statementIdx);
    }

    const userIndex = StatementHelper.getUserIndex(statement, userHashes);
    if (userIndex >= 0) {
      const attemptKey = statement.context?.extensions[EXTENSION_URL_SESSION_ID];
      if (attemptKey !== undefined) {
        // Add the attempt to the user for a module
        this.users[userIndex].addAttempt(
          attemptKey,
          statementIdx,
        );
      }
    }
  }

  /**
   * Get the module and the module index from a statement
   *
   * @param statement - A Statement object
   * @param moduleHashes - A list of module hashes
   * @param useTemplateIds - A boolean to indicate if template ids should be used
   * @param modules - A list of GroupedDataModule objects
   */
  public static getModule(
    statement: Statement,
    moduleHashes: Map<string, number>,
    useTemplateIds: boolean,
    modules: GroupedDataModule[],
  ): { module: GroupedDataModule | undefined, moduleIndex: number } {
    const moduleIndex = StatementHelper.getModuleIndex(
      statement,
      moduleHashes,
      useTemplateIds,
    );

    if (moduleIndex >= 0) {
      return { module: modules[moduleIndex], moduleIndex };
    }
    return { module: undefined, moduleIndex: -1 };
  }
}
