import { sha1 } from 'js-sha1';

import { AccountObject, Statement } from '../types/statement';

export default class InverseFunctionalIdentifier {
  /** The ifi hash */
  public get hash(): string {
    return this.#hash;
  }

  #account: AccountObject | undefined;

  #hash: string;

  #mbox: string | undefined;

  #mboxSha1Sum: string | undefined;

  /**
   * Create a new InverseFunctionalIdentifier
   *
   * @param mbox - The mbox of the actor
   * @param mboxSha1Sum - The mbox_sha1sum of the actor
   */
  public constructor({ account, mbox, mboxSha1Sum }:
  { account?: AccountObject, mbox?: string; mboxSha1Sum?: string }) {
    this.#account = account;
    this.#mbox = mbox;
    this.#mboxSha1Sum = mboxSha1Sum;

    this.#hash = InverseFunctionalIdentifier.claculateHash({
      account: this.#account,
      mbox: this.#mbox,
      mboxSha1Sum: this.#mboxSha1Sum,
    });
  }

  /**
   * Get the hash of the inverse functional identifier from a statement
   *
   * @param statement - A Statement object
   * @returns The hash of the inverse functional identifier
   */
  public static getHashFromStatement(statement: Statement): string {
    return InverseFunctionalIdentifier.claculateHash({
      account: statement.actor.account,
      mbox: statement.actor.mbox,
      mboxSha1Sum: statement.actor.mbox_sha1sum,
    });
  }

  /**
   * Calculate the hash of the inverse functional identifier. If there
   * is a mbox_sha1sum, use that. Otherwise, create a hash of the the mbox.
   *
   * @param mbox - The mbox of the actor
   * @param mboxSha1Sum - The mbox_sha1sum of the actor
   * @returns The hash of the inverse functional identifier
   */
  private static claculateHash({ account, mbox, mboxSha1Sum }:
  { account?: AccountObject, mbox?: string, mboxSha1Sum?: string }): string {
    if (account !== undefined) {
      return sha1(JSON.stringify(account));
    }
    if (mboxSha1Sum !== undefined) {
      return mboxSha1Sum;
    }
    if (mbox !== undefined) {
      return sha1(mbox);
    }

    throw new Error('No inverse functional identifier found');
  }
}
